            "⦿ 17: Prime, but less than 23.\n"
            "⦿ 24: Even and composite (divisible by 2, 3, etc.).\n"
            "⦿ 25: Ends in 5 and composite (divisible by 5).\n"
            "⦿ 29: Only has factors 1 and 29. Since 29 is greater than 23, it is the correct answer.",
