            "(b) Outline four measures the government can take to ensure efficient use of human resource in Ghana.\n",
        answer: "⦿ (a) Answer:\n\n"
            "• Skilled\n"
            "• Unskilled\n\n"
            "⦿ (b) Answer:\n\n"
