      PracticeQuestion(
        scenario: "Question 8: (a) State four effects of substance abuse.\n"
            "(b) Explain any four reasons for which substance abuse should be avoided.\n"
            "(BECE 2020 Q6)",
        answer: "Correct Answer: (a) Answer:\n"
            "⦿ Loss of life: Drug abuse triggers fatal medical issues like cardiac arrest, stroke, or cancer, directly leading to an early death.\n"
            "⦿ Decreased economic output: The cognitive and mental disruptions caused by addiction reduce performance, leading to work errors and chronic absenteeism.\n"
            "⦿ Descent into social vices: Addicts frequently turn to illegal survival behaviors like armed robbery, retail theft, prostitution, or physical assaults.\n"
            "⦿ Severe psychological degradation: Regular intake leads directly to visual hallucinations, extreme paranoia, memory loss, and irreversible madness.\n\n"
            "Answer: (b)\n"
            "⦿ To preserve personal health: Staying completely away from hard drugs like cocaine, heroin, or tramadol keeps your body free from organic damage, strokes, and deadly systemic failures.\n"
            "⦿ To protect family peace: Avoiding drug habits prevents severe financial strain and emotional conflict, ensuring that your home remains a peaceful and supportive place.\n"
            "⦿ To ensure steady career progress: Refusing dangerous chemicals protects your brain functions and focus, enabling you to successfully complete your education and build a stable economic future.\n"
            "⦿ To avoid early death: Steering clear of toxic street drugs removes the critical threat of fatal overdoses, organ damage, or unexpected health failures.\n"
            "⦿ To avoid organ damage: Staying drug-free keeps vital internal structures—like your liver, kidneys, heart, and lungs—safe from toxic destruction.\n"
            "⦿ To gain deep social respect: Choosing a sober, clean life earns you a reliable reputation, ensuring that neighbors, employers, and family elders hold you in high regard.\n"
            "⦿ To build national productivity: Maintaining a healthy body and sharp mind enables you to work efficiently, helping to drive the economic growth of your community and country.",
        explanation: ".",
      ),

      PracticeQuestion(
        scenario: "Question 9: (a) Highlight four causes of substance abuse by students.\n"
            "(b) Describe four ways in which substance abuse can be prevented.\n"
            "(BECE 2021 Q6)",
        answer: "Correct Answer: (a) Answer:\n"
            "⦿ Unsupervised experimenting: Taking illegal pills purely out of curiosity to see how they affect the brain.\n"
            "⦿ Peer group pressure: Falling into line with classmates who pressure you to try drugs to show you are independent.\n"
            "⦿ Misguided study methods: Wrongly assuming that popping stimulants is a smart way to study through the night without sleep.\n"
            "⦿ Broken homes: Missing strong parental supervision and guidance due to family separation or neglect.\n\n"
            "Answer: (b)\n"
            "⦿ Understanding legal penalties: Teaching youth about anti-drug laws to show them that using illegal substances leads directly to police arrest, court trials, and jail time.\n"
            "⦿ Protecting marital stability: Staying completely sober to avoid financial ruin, erratic tempers, and domestic violence, which helps maintain a stable marriage.\n"
            "⦿ Respecting your body: Remembering that your physical body is a sacred temple of God, which motivates you to keep it clean and free from harmful toxins.\n"
            "⦿ Proactive parenting: Parents must closely supervise their children's activities, monitor their choice of friends, and guide them away from harmful influences.\n"
            "⦿ Providing for children's basic needs: Ensuring that children have adequate food, clothes, and shelter so they are not tempted to sell drugs or turn to vice for survival money.\n"
            "⦿ Comprehensive drug education: Launching regular anti-drug awareness campaigns in schools, churches, and on television to erase ignorance about drug risks.\n"
            "⦿ Strict law enforcement: Backing law enforcement agencies and courts to fully enforce anti-drug laws and shut down local drug supply networks.\n"
            "⦿ Exposing local drug dealers: Encouraging citizens to report drug peddlers and their hideouts to the police to keep neighborhoods safe.\n"
            "⦿ Setting a positive example as leaders: Ensuring that parents, teachers, and community leaders live sober lives so the youth have positive role models to emulate.\n"
            "⦿ Educating expectant mothers: Ensuring that prenatal clinics advise pregnant women about the severe dangers that unprescribed drugs pose to their unborn babies.\n"
            "⦿ Hosting youth workshops: Organising regular workshops and lectures by NGOs to teach young people self-control and stress management skills.\n"
            "⦿ Funding rehabilitation centers: Providing adequate public funding and trained staff to rehabilitation clinics to help recovered addicts rebuild their lives safely.\n"
            "⦿ Shunning drug users: Intentionally avoiding social circles that use drugs like cocaine or marijuana, which pressures users to reconsider their habits.\n"
            "⦿ Banning illicit drug commerce: Writing and enforcing strict laws that outlaw any unauthorized sale or distribution of addictive chemicals.",
        explanation: ".",
      ),

