            "(BECE 2002A Q7)",
        answer: "Correct Answer: (a) Answer:\n"
            "⦿ Social work — This is the work we do to earn salary or wages at the end of every month. These people are referred to as civil or public servants, e.g., bankers, teachers, the police service, etc.\n"
            "⦿ House work — These are duties assigned to children to do at home by parents, e.g., sweeping, cooking, washing, etc.\n"
